'use client'

import { cn, useEffectPropSignal, useId, useSignalEffect } from '@cascivo/core'
import { useRef } from 'react'
import type { CSSProperties, KeyboardEvent } from 'react'
import styles from './wheel-picker.module.css'

export interface WheelPickerOption {
  value: string
  label: string
}

export interface WheelPickerProps {
  options: WheelPickerOption[]
  value: string
  onValueChange: (value: string) => void
  /**
   * How many rows are visible. Odd numbers keep the selection centred.
   *
   * @defaultValue `5`
   * @see the component manifest
   */
  visibleCount?: number
  /**
   * Row height in px.
   *
   * @defaultValue `36`
   * @see the component manifest
   */
  itemHeight?: number
  ariaLabel?: string
  /**
   * Alias of `ariaLabel` — same invisible accessible name, the other spelling. Not rendered.
   *
   * `ariaLabel` is the catalog convention and stays preferred, but `label` is the guess an
   * adopter makes when they have not read the convention, and an unaccepted guess costs a
   * compile cycle for nothing (2026-08-21 report item 1). Pass either.
   */
  label?: string
  className?: string
}

/** Settle time after the last scroll event before the centred row is committed. */
const SETTLE_MS = 120

/**
 * iOS-style drum picker: a column of options that scrolls and snaps to a centred selection.
 *
 * The wheel is CSS scroll-snap, not a JavaScript gesture engine — momentum, rubber-banding
 * and snapping are the platform's, so the whole gesture runs on the compositor and behaves
 * natively on every device. JavaScript only reads which row settled and moves the column
 * when the value changes from outside.
 *
 * Semantically a single-select listbox whose selection follows focus: Arrow keys, Home and
 * End move the selection and scroll to match, so there is nothing to confirm.
 */
export function WheelPicker({
  options,
  value,
  onValueChange,
  visibleCount = 5,
  itemHeight = 36,
  ariaLabel,
  label,
  className,
}: WheelPickerProps) {
  const columnRef = useRef<HTMLDivElement>(null)
  const baseId = useId()

  const selectedIndex = Math.max(
    0,
    options.findIndex((option) => option.value === value),
  )

  // Read at callback time only — the scroll handler runs outside the tracking scope.
  const optionsRef = useRef(options)
  optionsRef.current = options
  const onValueChangeRef = useRef(onValueChange)
  onValueChangeRef.current = onValueChange
  const itemHeightRef = useRef(itemHeight)
  itemHeightRef.current = itemHeight
  const valueRef = useRef(value)
  valueRef.current = value

  const scrollToIndex = (index: number, smooth: boolean): void => {
    const column = columnRef.current
    if (!column) return
    // 'instant', not 'auto': 'auto' defers to the CSS `scroll-behavior: smooth` below, which
    // would animate the initial placement — the wheel visibly spins up on every mount.
    column.scrollTo({
      top: index * itemHeightRef.current,
      behavior: smooth ? 'smooth' : 'instant',
    })
  }

  // Deferred mirror: this is read only inside the effect below, never during render, so a
  // synchronous mirror would run scrollTo mid-render.
  const targetValue = useEffectPropSignal(value)
  useSignalEffect(() => {
    const target = targetValue.value
    const index = optionsRef.current.findIndex((option) => option.value === target)
    if (index >= 0) scrollToIndex(index, false)
  })

  // Commit the centred row once scrolling has settled. Scroll-snap animates to the snap
  // point, so events keep arriving until it lands; a settle window covers both that and a
  // programmatic scroll.
  useSignalEffect(() => {
    const column = columnRef.current
    if (!column) return
    let timer: ReturnType<typeof setTimeout> | undefined

    const onScroll = (): void => {
      clearTimeout(timer)
      timer = setTimeout(() => {
        const index = Math.round(column.scrollTop / itemHeightRef.current)
        const option = optionsRef.current[index]
        if (option && option.value !== valueRef.current) onValueChangeRef.current(option.value)
      }, SETTLE_MS)
    }

    column.addEventListener('scroll', onScroll, { passive: true })
    return () => {
      clearTimeout(timer)
      column.removeEventListener('scroll', onScroll)
    }
  })

  const select = (index: number): void => {
    const clamped = Math.max(0, Math.min(options.length - 1, index))
    const option = options[clamped]
    if (!option || option.value === value) return
    onValueChange(option.value)
    scrollToIndex(clamped, true)
  }

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>): void => {
    const keys: Record<string, number> = {
      ArrowDown: selectedIndex + 1,
      ArrowUp: selectedIndex - 1,
      Home: 0,
      End: options.length - 1,
      PageDown: selectedIndex + visibleCount,
      PageUp: selectedIndex - visibleCount,
    }
    const next = keys[event.key]
    if (next === undefined) return
    event.preventDefault()
    select(next)
  }

  // The column is taller than one row, so half a column of padding above and below lets the
  // first and last options reach the centre.
  const pad = ((visibleCount - 1) / 2) * itemHeight
  const rootStyle = {
    '--_item-height': `${itemHeight}px`,
    '--_pad': `${pad}px`,
    '--_column-height': `${visibleCount * itemHeight}px`,
  } as CSSProperties

  return (
    <div className={cn(styles['root'], className)} style={rootStyle}>
      <div
        ref={columnRef}
        role="listbox"
        tabIndex={0}
        aria-label={ariaLabel ?? label}
        aria-activedescendant={`${baseId}-${selectedIndex}`}
        className={styles['column']}
        onKeyDown={onKeyDown}
      >
        {options.map((option, index) => (
          <div
            key={option.value}
            id={`${baseId}-${index}`}
            role="option"
            aria-selected={index === selectedIndex}
            className={styles['option']}
          >
            {option.label}
          </div>
        ))}
      </div>
      {/* Decorative: the band marks where the selection sits. */}
      <div aria-hidden="true" className={styles['band']} />
    </div>
  )
}

@layer cascivo.component {
  .root {
    position: relative;
    inline-size: fit-content;
  }

  .column {
    block-size: var(--_column-height);
    overflow-y: auto;
    /* The wheel itself: the platform owns momentum, rubber-banding and the snap. */
    scroll-snap-type: y mandatory;
    scrollbar-width: none;
    /* Half a column top and bottom so the first and last rows can reach the centre. */
    padding-block: var(--_pad);
    /* Drum falloff — rows dim towards the ends instead of being clipped flat. */
    mask-image: linear-gradient(to bottom, transparent 0%, black 25%, black 75%, transparent 100%);

    &::-webkit-scrollbar {
      display: none;
    }

    &:focus-visible {
      outline: var(--cascivo-ring-width) solid var(--cascivo-ring-color);
      outline-offset: 2px;
      border-radius: var(--cascivo-radius-md);
    }
  }

  .option {
    display: flex;
    align-items: center;
    justify-content: center;
    block-size: var(--_item-height);
    scroll-snap-align: center;
    padding-inline: var(--cascivo-space-4);
    color: var(--cascivo-color-text-muted);
    font-size: var(--cascivo-text-ui);
    white-space: nowrap;
    /* Rows are snap targets; a text selection drag would fight the wheel. */
    user-select: none;

    &[aria-selected='true'] {
      color: var(--cascivo-color-foreground);
      font-weight: var(--cascivo-font-semibold);
    }
  }

  .band {
    position: absolute;
    inset-inline: 0;
    inset-block-start: 50%;
    translate: 0 -50%;
    block-size: var(--_item-height);
    border-block: 1px solid var(--cascivo-border-subtle);
    pointer-events: none;
  }

  @media (prefers-reduced-motion: no-preference) {
    .column {
      scroll-behavior: smooth;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'WheelPicker',
  description: 'iOS-style drum picker — a column of options that scrolls and snaps to a selection',
  category: 'inputs',
  clientJs: 'required',
  states: ['idle', 'focused', 'scrolling'],
  variants: [],
  sizes: [],
  props: [
    {
      name: 'options',
      type: 'WheelPickerOption[]',
      required: true,
      description: 'The rows of the wheel, in order',
    },
    {
      name: 'value',
      type: 'string',
      required: true,
      description: 'The selected option value; the component is controlled',
    },
    {
      name: 'onValueChange',
      type: '(value: string) => void',
      required: true,
      description: 'Called with the new value when the wheel settles or a key moves the selection',
    },
    {
      name: 'visibleCount',
      type: 'number',
      required: false,
      default: '5',
      description: 'How many rows are visible. Odd numbers keep the selection centred.',
    },
    {
      name: 'itemHeight',
      type: 'number',
      required: false,
      default: '36',
      description: 'Row height in px.',
    },
    {
      name: 'label',
      nameVisibility: 'invisible',
      description:
        'Alias of `ariaLabel` — the same invisible accessible name under the other spelling. Neither is deprecated.',
      type: 'string',
      required: false,
    },
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      type: 'string',
      required: false,
      description: 'Accessible label for the wheel — required when it has no visible label',
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  typeDefs: [
    {
      name: 'WheelPickerOption',
      fields: [
        { name: 'value', type: 'string', required: true, description: 'Value reported on change' },
        { name: 'label', type: 'string', required: true, description: 'Visible row text' },
      ],
    },
  ],
  tokens: [
    '--cascivo-color-foreground',
    '--cascivo-color-text-muted',
    '--cascivo-border-subtle',
    '--cascivo-text-ui',
    '--cascivo-font-semibold',
    '--cascivo-radius-md',
    '--cascivo-ring-width',
    '--cascivo-ring-color',
  ],
  accessibility: {
    role: 'listbox',
    wcag: '2.2-AA',
    keyboard: ['ArrowUp', 'ArrowDown', 'Home', 'End', 'PageUp', 'PageDown', 'Tab'],
    reducedMotion: true,
  },
  examples: [
    {
      title: 'Basic',
      code: `<WheelPicker
  ariaLabel="Hour"
  value={hour}
  onValueChange={setHour}
  options={[
    { value: '09', label: '09' },
    { value: '10', label: '10' },
    { value: '11', label: '11' },
  ]}
/>`,
      description: 'Controlled — the caller owns the value.',
    },
    {
      title: 'Taller wheel',
      code: `<WheelPicker ariaLabel="Minute" value={minute} onValueChange={setMinute} options={minutes} visibleCount={7} />`,
      description: 'Shows more rows around the selection.',
    },
    {
      title: 'Several columns',
      code: `<Flex gap="0">
  <WheelPicker ariaLabel="Hour" value={hour} onValueChange={setHour} options={hours} />
  <WheelPicker ariaLabel="Minute" value={minute} onValueChange={setMinute} options={minutes} />
</Flex>`,
      description: 'Compose one wheel per field; each column is independently operable.',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['inputs', 'picker', 'wheel', 'drum', 'scroll-snap', 'mobile', 'ios'],
  intent: {
    whenToUse: [
      'Touch surfaces picking one value from a short, ordered, homogeneous range — an hour, a minute, a unit',
      'Mobile forms following the platform convention of a drum rather than a dropdown',
      'Inside a BottomSheet or ActionSheet, where a native select would open a competing overlay',
    ],
    whenNotToUse: [
      'Long or unordered option lists, where scrolling to a value is slower than typing — use Combobox',
      'Desktop, pointer-first forms — use Select or NativeSelect',
      'Dates, which have their own affordances — use DatePicker or Calendar',
    ],
    antiPatterns: [
      {
        bad: 'Rendering it uncontrolled and reading the value from the DOM',
        good: 'Pass `value` and `onValueChange`',
        why: 'The component is controlled; without a `value` it cannot scroll to the current selection or reflect an external change',
      },
      {
        bad: 'Leaving `ariaLabel` off a wheel with no visible label',
        good: 'Label every column — "Hour", "Minute"',
        why: 'A listbox with no accessible name is announced only as a list, so the user cannot tell which field they are in',
      },
    ],
    related: [
      {
        name: 'Select',
        relationship: 'alternative',
        reason: 'Pointer-first single selection on desktop',
      },
      {
        name: 'TimePicker',
        relationship: 'alternative',
        reason: 'Purpose-built time entry rather than a generic wheel',
      },
      {
        name: 'BottomSheet',
        relationship: 'pairs-with',
        reason: 'The usual host for a wheel on a phone screen',
      },
    ],
    a11yRationale:
      'The column is a role="listbox" with role="option" rows, is focusable, and points aria-activedescendant at the selected row, so assistive technology tracks the selection without moving DOM focus per row. Selection follows focus — ArrowUp/ArrowDown, Home/End and PageUp/PageDown move the selection and scroll to match — which is the APG single-select listbox variant that needs no explicit commit; the pattern is deliberately not declared as `apgPattern: listbox` because that guard requires an Enter key this variant has nothing to bind. The wheel itself is CSS scroll-snap, so touch momentum and rubber-banding are the platform\'s own and remain correct under assistive gestures. Smooth scrolling is applied only under prefers-reduced-motion: no-preference. The selection band is decorative and aria-hidden.',
    flexibility: [
      {
        area: 'visibleCount / itemHeight',
        level: 'flexible',
        note: 'Wheel geometry is caller-controlled (defaults 5 rows of 36px)',
      },
      {
        area: 'value / onValueChange',
        level: 'strict',
        note: 'Always controlled — the component never holds the value itself',
      },
      {
        area: 'wheel mechanism',
        level: 'strict',
        note: 'Always CSS scroll-snap; there is no JavaScript-driven transform mode',
      },
    ],
  },
}
